package com.company.tpm.schedule;import com.company.tpm.common.BaseEntity;import com.company.tpm.training.TrainingCourse;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="training_sessions")public class TrainingSession extends BaseEntity{@ManyToOne(optional=false,fetch=FetchType.LAZY)private TrainingCourse course;@Column(nullable=false)private LocalDate sessionDate;@Column(nullable=false)private LocalTime startTime;@Column(nullable=false)private LocalTime endTime;private String location;private String instructor;private String notes;@Enumerated(EnumType.STRING)@Column(nullable=false)private Status status=Status.SCHEDULED;public enum Status{DRAFT,SCHEDULED,IN_PROGRESS,COMPLETED,CANCELLED}protected TrainingSession(){}public TrainingSession(TrainingCourse c,LocalDate d,LocalTime s,LocalTime e){if(!e.isAfter(s))throw new IllegalArgumentException("End time must be after start time");course=c;sessionDate=d;startTime=s;endTime=e;}public LocalDate getSessionDate(){return sessionDate;}public LocalTime getStartTime(){return startTime;}public LocalTime getEndTime(){return endTime;}public Status getStatus(){return status;}}
